    /**
     * Method to retrieve the Order via OrderFetchOneSummary
     * @param 	summary OrderFetchOneSummary 
     * @return 	OrderFetchOneResponse
     * @exception ProcessingException - Thrown if processing any related problems
     * @exception IllegalArgumentException 
     */
    public Order getOrder( OrderFetchOneSummary summary ) 
    throws ProcessingException, IllegalArgumentException {
    	
    	if( summary == null )
    		throw new IllegalArgumentException( "OrderFetchOneSummary arg cannot be null" );
    	
    	Order entity = null;
    	
        try {
        	// --------------------------------------
        	// validate the fetch one summary
        	// --------------------------------------    	
        	validator.validate( summary );    
        	
        	// --------------------------------------
        	// use queryGateway to send request to Find a Order
        	// --------------------------------------
        	CompletableFuture<Order> futureEntity = queryGateway.query(new FindOrderQuery( new LoadOrderFilter( summary.getOrderId() ) ), ResponseTypes.instanceOf(Order.class));
        	
        	entity = futureEntity.get();
        }
        catch( Exception exc ) {
            final String errMsg = "Unable to locate Order with id " + summary.getOrderId();
            LOGGER.log( Level.WARNING, errMsg, exc );
            throw new ProcessingException( errMsg, exc );
        }
        finally {
        }        
        
        return entity;
    }


